+            query.explainMatch(boost, dummyDescription),
+            equalTo(
+                Explanation.match(
+                    boost,
+                    dummyDescription,
+                    Explanation.match(
+                        boost,
+                        "boost * runtime_field_score",
+                        Explanation.match(boost, "boost"),
